// Brand design tokens: the ONLY file of the web allowed to contain hex
// colours (RF-17, checked by no-loose-colors.test.ts). Pages and components
// use the CSS custom properties generated by `tokensToCss`.

export type ColorToken = {
  /** Hex value. */
  value: string;
  /** What the colour is used for. */
  role: string;
};

export const colors = {
  bgDark: { value: "#1D003F", role: "Dark background (header, footer)" },
  bg: { value: "#34006F", role: "Background" },
  button: { value: "#FFC300", role: "Button" },
  buttonHover: {
    value: "#FFE000",
    role: "Button on hover/focus, focus ring and yellow accent text",
  },
  logoGradient1: { value: "#FF9D00", role: "Logo gradient, stop 1" },
  logoGradient2: { value: "#FF6700", role: "Logo gradient, stop 2" },
  logoGradient3: { value: "#FF5733", role: "Logo gradient, stop 3" },
  logoGradient4: { value: "#C70039", role: "Logo gradient, stop 4" },
  accentGreen: { value: "#DAF7A6", role: "Light green accent (links)" },
  text: { value: "#FFFFFF", role: "Neutral: text on dark backgrounds" },
  // Solid backgrounds of the service blocks (contrast checked in
  // styles/contrast.test.ts). Proposed values, pending visual review.
  planetHexawebBg: {
    value: "#00505C",
    role: "Hexaweb service block background (dark teal)",
  },
  planetRankiaBg: {
    value: "#1F2A7A",
    role: "Rankia service block background (indigo)",
  },
  planetAdaraBg: {
    value: "#7A1A12",
    role: "Adara service block background (dark red)",
  },
} as const satisfies Record<string, ColorToken>;

export type ColorName = keyof typeof colors;

/** CSS custom property of a colour token: `logoGradient1` → `--color-logo-gradient-1`. */
export function cssVariableName(name: string): string {
  const kebab = name
    .replace(/([a-z])([A-Z0-9])/g, "$1-$2")
    .replace(/([0-9])([A-Za-z])/g, "$1-$2")
    .toLowerCase();
  return `--color-${kebab}`;
}

/** `:root` rule declaring one custom property per colour token. */
export function tokensToCss(tokens: Record<string, ColorToken>): string {
  const declarations = Object.entries(tokens)
    .map(([name, token]) => `${cssVariableName(name)}:${token.value};`)
    .join("");
  return `:root{${declarations}}`;
}

// Brand typography (RF-18): self-hosted woff2 files (latin subset) in
// FONTS_DIR, licensed under the SIL OFL 1.1 (see NOTICE.md there). The
// Astro config builds its `fonts` families from these tokens.

/** Folder of the font files, relative to the web app root (apps/web). */
export const FONTS_DIR = "./src/assets/fonts/";

export type FontVariant = {
  weight: 400 | 700;
  style: "normal";
  /** File name inside FONTS_DIR. */
  file: string;
  /** Preloaded in every page (plan, D8: only the critical weights). */
  preload: boolean;
};

export type FontToken = {
  /** Family name as declared in @font-face. */
  name: string;
  /** CSS custom property that holds the font stack. */
  cssVariable: `--font-${string}`;
  /** Generic family used for the metric-adjusted fallback. */
  fallbacks: readonly string[];
  variants: readonly FontVariant[];
};

export const fonts = {
  heading: {
    name: "Lilita One",
    cssVariable: "--font-heading",
    fallbacks: ["sans-serif"],
    variants: [
      {
        weight: 400,
        style: "normal",
        file: "lilita-one-latin-400-normal.woff2",
        preload: true,
      },
    ],
  },
  body: {
    name: "Lato",
    cssVariable: "--font-body",
    fallbacks: ["sans-serif"],
    variants: [
      {
        weight: 400,
        style: "normal",
        file: "lato-latin-400-normal.woff2",
        preload: true,
      },
      {
        weight: 700,
        style: "normal",
        file: "lato-latin-700-normal.woff2",
        preload: false,
      },
    ],
  },
} as const satisfies Record<string, FontToken>;

/** Variants to pass to `<Font preload={…}>`: only the preloaded ones. */
export function fontPreloads(
  token: FontToken,
): { weight: FontVariant["weight"]; style: FontVariant["style"] }[] {
  return token.variants
    .filter((variant) => variant.preload)
    .map(({ weight, style }) => ({ weight, style }));
}

/**
 * Families for the `fonts` option of the Astro config, using the given
 * provider (`fontProviders.local()` there; a stub in the tests). Every
 * variant uses `font-display: swap` (RF-19).
 */
export function fontFamilies<P>(
  tokens: Record<string, FontToken>,
  provider: P,
) {
  return Object.values(tokens).map((token) => ({
    provider,
    name: token.name,
    cssVariable: token.cssVariable,
    fallbacks: [...token.fallbacks],
    options: {
      variants: token.variants.map(({ weight, style, file }) => ({
        weight,
        style,
        display: "swap" as const,
        src: [FONTS_DIR + file],
      })),
    },
  }));
}
